function decodificar(b64) {
  // Los binarios viajan en base64 dentro del item mientras el modo de binarios
  // sea el de memoria, que es el de serie. Buffer existe en el nodo Code, pero
  // el runner podria no exponerlo: de ahi el plan B.
  if (typeof Buffer !== 'undefined') return Buffer.from(b64, 'base64').toString('utf8');
  const bin = atob(b64);
  return new TextDecoder('utf-8').decode(Uint8Array.from(bin, (c) => c.charCodeAt(0)));
}

function leerVault() {
  // Segun la version de n8n, el nodo de lectura saca un item por fichero o un
  // solo item con data0, data1... Recorremos items y propiedades a la vez, que
  // cubre las dos formas sin preguntar.
  const ficheros = [];
  for (const item of $input.all()) {
    for (const clave of Object.keys(item.binary ?? {})) {
      const b = item.binary[clave];
      if (!b || typeof b.data !== 'string') continue;
      ficheros.push({
        nombre: b.fileName ?? clave,
        texto: decodificar(b.data),
      });
    }
  }
  return ficheros;
}

function frontmatter(texto) {
  // Un parser de YAML de tres lineas. Solo hay que leer lo que escribe
  // "Componer nota", que son pares clave: valor planos.
  const m = texto.match(/^---\r?\n([\s\S]*?)\r?\n---/);
  if (!m) return {};
  const campos = {};
  for (const linea of m[1].split(/\r?\n/)) {
    const i = linea.indexOf(':');
    if (i === -1) continue;
    const clave = linea.slice(0, i).trim();
    let valor = linea.slice(i + 1).trim();
    if (valor.startsWith('"') && valor.endsWith('"')) {
      valor = valor.slice(1, -1).replace(/\\"/g, '"');
    }
    campos[clave] = valor;
  }
  return campos;
}

// Modo: Run Once for All Items.
// Herramienta "agenda" del agente. Lee el vault y devuelve los eventos con
// fecha en una ventana alrededor de hoy, ya ordenados y en texto: al modelo le
// sale mejor leer una lista de frases que un JSON con fechas ISO.

const DIAS = ['lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado', 'domingo'];
const MESES = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio',
               'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];

const ahora = DateTime.now().setZone('Europe/Madrid');
// Una semana hacia atras para poder contestar "¿no era ayer lo del dentista?",
// y dos meses hacia delante, que es hasta donde llega una agenda personal.
const desde = ahora.minus({ days: 7 });
const hasta = ahora.plus({ days: 60 });

const eventos = [];
for (const f of leerVault()) {
  const fm = frontmatter(f.texto);
  if (!fm.cuando) continue;                  // sin fecha no es evento
  const d = DateTime.fromISO(fm.cuando, { zone: 'Europe/Madrid' });
  if (!d.isValid || d < desde || d > hasta) continue;
  eventos.push({ d, titulo: fm.titulo || f.nombre, fichero: f.nombre });
}

eventos.sort((a, b) => a.d.toMillis() - b.d.toMillis());

const lineas = eventos.map((e) => {
  const cuando = DIAS[e.d.weekday - 1] + ' ' + e.d.day + ' de ' +
    MESES[e.d.month - 1] + ' de ' + e.d.year + ' a las ' + e.d.toFormat('HH:mm');
  return '- ' + cuando + (e.d < ahora ? ' (ya pasó)' : '') + ': ' + e.titulo;
});

const cabecera = 'Hoy es ' + DIAS[ahora.weekday - 1] + ' ' +
  ahora.toFormat('dd/LL/yyyy') + ' y son las ' + ahora.toFormat('HH:mm') + '.';

const respuesta = lineas.length
  ? cabecera + '\nEventos apuntados entre el ' + desde.toFormat('dd/LL') +
    ' y el ' + hasta.toFormat('dd/LL') + ':\n' + lineas.join('\n')
  : cabecera + '\nNo hay ningún evento apuntado entre el ' +
    desde.toFormat('dd/LL') + ' y el ' + hasta.toFormat('dd/LL') + '.';

return [{ json: { response: respuesta } }];
